static int Sep(const void*a,size_t an,const void*b,size_t bn){uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return a&&b&&an&&bn&&an<=UINTPTR_MAX-x&&bn<=UINTPTR_MAX-y&&(x+an<=y||y+bn<=x);}
static int TargetValid(const VMX_CR3_TARGET_SET*t){uint64_t mask;uint32_t i,j;if(!t||t->Version!=VMX_CR3_TARGET_SET_VERSION||!t->Count||t->Count>VMX_CR3_TARGET_MAX_ROOTS||t->PhysicalAddressBits<36||t->PhysicalAddressBits>52||t->PcideEnabled>1||!t->Generation||t->Reserved)return 0;mask=(UINT64_C(1)<<t->PhysicalAddressBits)-1;for(i=0;i<t->Count;i++){if(!t->Roots[i]||(t->Roots[i]&~VMX_CR3_TARGET_PAGE_MASK)||(t->Roots[i]&~mask))return 0;for(j=0;j<i;j++)if(t->Roots[i]==t->Roots[j])return 0;}for(;i<VMX_CR3_TARGET_MAX_ROOTS;i++)if(t->Roots[i])return 0;return 1;}
static int IdentityValid(const VMX_PROCESSOR_IDENTITY*x,size_t i){return x->SystemIndex==i&&x->Number<VMX_PROCESSOR_GROUP_MAX_NUMBER&&!x->Reserved;}
static int StateValid(const VMX_CR3_TARGET_SET*t,const VMX_CR3_RESIDENCY_STATE*s){if(s->Version!=VMX_CR3_RESIDENCY_STATE_VERSION||s->Resident>1||s->TargetGeneration!=t->Generation||s->Busy||s->Reserved32||s->Reserved)return 0;if(!s->Resident)return s->MatchedIndex==UINT32_MAX&&!s->Pcid&&!s->NormalizedRoot;return s->MatchedIndex<t->Count&&s->Pcid<=VMX_CR3_TARGET_PCID_MASK&&s->NormalizedRoot==t->Roots[s->MatchedIndex]&&(t->PcideEnabled||!s->Pcid);}
static int ViewValid(const VMX_CR3_PUBLIC_STATUS_VIEW*v){size_t i,j;if(v->Version!=HYPERVISOR_CR3_STATUS_VERSION||v->HeaderSize!=HYPERVISOR_CR3_STATUS_HEADER_SIZE||v->RecordSize!=HYPERVISOR_CR3_STATUS_RECORD_SIZE||v->Reserved||!v->OwnerGeneration||v->IdentityCount!=v->StateCount||!v->StateCount||!TargetValid(v->Target))return 0;for(i=0;i<v->StateCount;i++){if(!IdentityValid(&v->Identities[i],i)||!StateValid(v->Target,&v->States[i]))return 0;for(j=0;j<i;j++)if(v->Identities[i].Group==v->Identities[j].Group&&v->Identities[i].Number==v->Identities[j].Number)return 0;}return 1;}
VMX_CR3_PUBLIC_STATUS_RESULT VmxCr3PublicStatusEncode(const VMX_CR3_PUBLIC_STATUS_VIEW*v,void*out,size_t out_size,size_t*required){HYPERVISOR_CR3_STATUS_HEADER h={0};size_t ib,sb,total,i;uint64_t transitions=0;uint32_t residents=0;if(!v||!required||(out_size&&!out)||!v->Target||!v->Identities||!v->States)return VMX_CR3_PUBLIC_STATUS_INVALID;if(v->IdentityCount>SIZE_MAX/sizeof(*v->Identities)||v->StateCount>SIZE_MAX/sizeof(*v->States))return VMX_CR3_PUBLIC_STATUS_OVERFLOW;ib=v->IdentityCount*sizeof(*v->Identities);sb=v->StateCount*sizeof(*v->States);if(!Sep(v,sizeof(*v),required,sizeof(*required))||!Sep(v->Target,sizeof(*v->Target),required,sizeof(*required))||!Sep(v->Identities,ib,required,sizeof(*required))||!Sep(v->States,sb,required,sizeof(*required))||(out&&(!Sep(v,sizeof(*v),out,out_size)||!Sep(v->Target,sizeof(*v->Target),out,out_size)||!Sep(v->Identities,ib,out,out_size)||!Sep(v->States,sb,out,out_size)||!Sep(required,sizeof(*required),out,out_size))))return VMX_CR3_PUBLIC_STATUS_INVALID;*required=0;if(out)memset(out,0,out_size);if(!ViewValid(v))return VMX_CR3_PUBLIC_STATUS_INVALID;if(v->StateCount>UINT32_MAX||v->StateCount>(SIZE_MAX-HYPERVISOR_CR3_STATUS_HEADER_SIZE)/HYPERVISOR_CR3_STATUS_RECORD_SIZE)return VMX_CR3_PUBLIC_STATUS_OVERFLOW;total=HYPERVISOR_CR3_STATUS_HEADER_SIZE+v->StateCount*HYPERVISOR_CR3_STATUS_RECORD_SIZE;if(total>UINT32_MAX)return VMX_CR3_PUBLIC_STATUS_OVERFLOW;for(i=0;i<v->StateCount;i++){if(UINT64_MAX-transitions<v->States[i].TransitionSequence)return VMX_CR3_PUBLIC_STATUS_OVERFLOW;transitions+=v->States[i].TransitionSequence;residents+=v->States[i].Resident;}*required=total;if(!out||out_size<total)return VMX_CR3_PUBLIC_STATUS_BUFFER_TOO_SMALL;h.Version=HYPERVISOR_CR3_STATUS_VERSION;h.HeaderSize=HYPERVISOR_CR3_STATUS_HEADER_SIZE;h.RecordSize=HYPERVISOR_CR3_STATUS_RECORD_SIZE;h.TotalSize=(uint32_t)total;h.OwnerGeneration=v->OwnerGeneration;h.TargetGeneration=v->Target->Generation;h.ContextCount=(uint32_t)v->StateCount;h.TargetCount=v->Target->Count;h.PhysicalAddressBits=v->Target->PhysicalAddressBits;h.Flags=HYPERVISOR_CR3_STATUS_FLAG_AUTHENTICATED|(v->Target->PcideEnabled?HYPERVISOR_CR3_STATUS_FLAG_PCIDE_ENABLED:0)|(residents?HYPERVISOR_CR3_STATUS_FLAG_ANY_RESIDENT:0)|(transitions?HYPERVISOR_CR3_STATUS_FLAG_ANY_TRANSITION:0);h.ResidentCount=residents;h.TotalTransitions=transitions;memcpy(out,&h,sizeof(h));for(i=0;i<v->StateCount;i++){HYPERVISOR_CR3_STATUS_RECORD r={0};r.SystemIndex=(uint32_t)i;r.Group=v->Identities[i].Group;r.Number=v->Identities[i].Number;r.Resident=(uint8_t)v->States[i].Resident;r.MatchedIndex=v->States[i].MatchedIndex;r.Pcid=v->States[i].Pcid;r.TransitionSequence=v->States[i].TransitionSequence;memcpy((unsigned char*)out+sizeof(h)+i*sizeof(r),&r,sizeof(r));}return VMX_CR3_PUBLIC_STATUS_OK;}